import json,shutil,html
def build_membership(page,url,ROOT,DIST):
    records=json.loads((ROOT/"data/directory.json").read_text())
    firms={f["name"]:f for f in json.loads((ROOT/"data/prop.json").read_text())["firms"].values()}
    data=[{"name":r["name"],"plans":firms.get(r["name"],{}).get("plans",[])+r.get("account_plans",[])} for r in records]
    payload=json.dumps(data,ensure_ascii=True).replace("<","\\u003c")
    body=f"""<section class="member-hero"><div class="eyebrow">PERSONAL TRADING WORKSPACE</div><h1>Your trading business, organized.</h1><p>Track accounts, trading days, expenses and actual payouts in one place.</p><p class="member-notice">Interactive local preview · No registration, cloud storage or payments connected. Use synthetic data only.</p><a class="btn" href="{url('membership/')}">Compare memberships</a></section>
<section id="member-app" class="member-shell"><aside class="member-nav" aria-label="Workspace navigation"><strong>Command center</strong><label for="member-tier">Preview membership</label><select id="member-tier"><option value="free">Free · 1 account</option><option value="pro">Pro · 10 accounts</option><option value="elite">Elite · 25 accounts</option></select><div id="member-nav"></div></aside><div class="member-main"><div class="member-heading"><div><p class="eyebrow" id="member-context"></p><h2 id="member-title">Overview</h2></div><button type="button" class="btn" id="member-reset">Reset demo data</button></div><p id="member-status" role="status" class="note"></p><div id="member-content"></div></div></section>
<script id="member-data" type="application/json">{payload}</script><script defer src="{url('membership.js')}"></script>"""
    page("account/","Trading command center | PropFirmMath","Preview the personal account management workspace.",body,crumbs=[("Home",""),("Account","account/")])
    pricing=f"""<section class="member-hero"><div class="eyebrow">MEMBERSHIP</div><h1>Choose your trading workspace.</h1><p>One account to get started. More capacity and intelligence as your trading business grows.</p><p class="member-notice">Preview prices only. Billing country verification and checkout are not connected.</p></section><div class="member-prices">"""
    for name,price,annual,limit,features in [("Free","$0","$0",1,["Basic daily journal","One active account","Basic target and consistency tracking"]),("Pro","$14.99","$119.99",10,["Premium workspace","Bulk journal entries","Calendar, expenses and payouts","Portfolio analytics and CSV export"]),("Elite","$29.99","$249.99",25,["All Pro features","25 active accounts","Consolidated reporting","Advanced portfolio risk — planned","Priority support — planned"])]:
        pricing+=f'<article class="card member-price"><h2>{name}</h2><div class="big">{price}<small> / month</small></div><p>{annual} annually · US baseline</p><h3>{limit} active account'+('s' if limit!=1 else '')+'</h3><ul>'+''.join('<li>'+html.escape(x)+'</li>' for x in features)+f'</ul><a class="btn" href="{url("account/")}">Explore workspace demo</a></article>'
    pricing+='</div><h2>Regional billing</h2><p>Final prices will be determined by verified billing country, not the public research-country selector. No payments are accepted in this preview.</p>'
    page("membership/","Membership | PropFirmMath","Free, Pro and Elite workspace plans.",pricing,crumbs=[("Home",""),("Membership","membership/")])
    shutil.copy(ROOT/"src/membership.js",DIST/"membership.js")
    shutil.copy(ROOT/"src/membership.css",DIST/"membership.css")
